import { Component, h, Prop, Element, Host } from '@stencil/core';
import classnames from 'classnames';
import { KsTextVariant } from '../../ks-text/types';
const prefix = 'skeleton-text';

@Component({
  tag: 'ks-skeleton-text',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsSkeletonText {
  ['x-name'] = 'ks-skeleton-text';
  // @ts-expect-error TYPE_FIXME. Please Fix the below strict mode type error. Read https://bytedance.sg.larkoffice.com/docx/MIsKdGOQwoQsnuxrsxEl6AsYgCf
  @Element() el: HTMLKsSkeletonTextElement;
  /** The type of the skeleton text, affecting its style (e.g., headline, paragraph). */
  @Prop() variant: KsTextVariant = 'bodySm';

  render() {
    const cls = classnames('ks-skeleton', prefix, `${prefix}-${this.variant}`);
    return (
      <Host class="KsSkeletonText" aria-hidden="true">
        <span class={cls}></span>
      </Host>
    );
  }
}
